    if (str[i] != '+') {
      for (int j = (0), _j = (k); j < _j; ++j)
        str[i + j] = (str[i + j] == '+') ? '-' : '+';
      res++;
    }
  }
  bool flag = true;
  for (int i = (0), _i = (n); i < _i; ++i) {
    if (str[i] != '+')
      flag = false;
  }
  if (flag)
    printf("%d\n", res);
  else
    printf("IMPOSSIBLE\n");
}

int main() {
  int T;
  scanf("%d", &T);
  for (int cas = 1; cas <= T; cas++) {
    printf("Case #%d: ", cas);
    solve();
  }
}
