int main(void) {
  int t;
  scanf("%d", &t);
  for (int tt = 1; tt <= t; tt++) {

    int n, k;
    priority_queue<int> q;
    scanf("%d%d", &n, &k);
    q.push(n);
    while (--k) {
      int x = q.top();
      q.pop();
      q.push(x / 2);
      q.push((x - 1) / 2);
    }

    int v = q.top();
    printf("Case #%d: %d %d\n", tt, v / 2, (v - 1) / 2);
  }
  return 0;
}

